export interface AttemptResultDocument {
  agent_invocations: number;
  capabilities_used: string[];
  cleanup_warning: string | null;
  error: ResultError | null;
  evidence_path: string;
  gold_materialized_at: string;
  kind: string;
  limit: string | null;
  logs: string;
  metrics: Record<string, unknown>;
  score: number | null;
  status: "PASS" | "FAIL" | "ERROR";
  fork?: ForkProvenance;
}

export interface FactDocument {
  phase: string;
  name: string;
  detail?: Record<string, unknown>;
}

export interface ForkChange {
  role: string;
  path: string;
  from: string;
  to: string;
}

export interface ForkProvenance {
  format: "ageval.fork/1";
  parent_attempt_id: string;
  checkpoint_seq: number;
  source_locked_config_digest: string;
  child_locked_config_digest: string;
  source_model: string;
  continuation_model: string;
  continuation_model_verified: boolean;
  context_conversion: string;
  executor_kind: string;
  changes: ForkChange[];
  shared_prefix_usage?: MeasuredUsage;
}

export interface MeasuredUsage {
  prompt_tokens?: number;
  completion_tokens?: number;
  cached_tokens?: number;
  cost_usd?: number;
}

export interface PhaseTimingDocument {
  schema: "ageval.phase_timing/1";
  phases: PhaseTimingPhase[];
  total_ms: number;
  started_at?: string;
  finished_at?: string;
}

export interface PhaseTimingPhase {
  id: string;
  label: string;
  duration_ms: number;
}

export interface ResultError {
  phase: string | null;
  title: string;
  message: string;
}

export interface SummaryDocument {
  schema: "ageval.evidence.summary/1";
  attempt_id: string;
  run_id: string;
  evidence_root: string;
  result: AttemptResultDocument;
  facts: FactDocument[];
  phase_timing: PhaseTimingDocument;
  keep_vendor_raw: boolean;
  extra?: Record<string, unknown>;
  fork?: ForkProvenance;
}

export interface TerminalRow {
  type: "terminal";
  ok: boolean;
  error: string | null;
  turn_index: number;
  session_id: string | null;
  structured: Record<string, unknown> | null;
  usage: TerminalUsage;
  stop_reason: string | null;
  metadata: Record<string, unknown>;
  source: "ageval";
  extra?: Record<string, unknown>;
  elapsed_ms?: number;
  profile_id?: string;
}

export type TerminalUsage = MeasuredUsage | UnavailableUsage;

export interface UnavailableUsage {
  unavailable: "not_reported" | "lost_on_timeout" | "parse_failed" | "partial";
  prompt_tokens?: number;
  completion_tokens?: number;
  cached_tokens?: number;
  cost_usd?: number;
}

